package com.tekwatt.payment.dto;import com.tekwatt.payment.entity.PaymentGatewayConfig;import java.time.Instant;import java.util.UUID;public record GatewayConfigResponse(UUID id,UUID tenantId,String provider,boolean enabled,String publicKey,boolean secretConfigured,String upiVpa,String payeeName,Instant updatedAt){public static GatewayConfigResponse from(PaymentGatewayConfig c){return new GatewayConfigResponse(c.getId(),c.getTenantId(),c.getProvider(),c.isEnabled(),c.getPublicKey(),c.hasSecret(),c.getUpiVpa(),c.getPayeeName(),c.getUpdatedAt());}}
